<template>
  <div class="platform" @pointerdown="touch" @keydown="touch">
    <div v-if="!user" class="login-layout">
      <section class="login-intro"><span class="brand"><ShieldCheck :size="24" /> MEMBER / PLATFORM</span><h1>全门店管理，<br />清晰的权限边界。</h1><p>面向平台管理员、运营人员与开发者的独立控制台。集中管理门店、商业授权、账号与审计记录。</p><div class="intro-note">平台身份与商家身份独立<br />所有管理变更均保留审计记录</div></section>
      <section class="login-card"><span class="eyebrow">平台控制台</span><h2>登录平台账号</h2><p>请使用平台管理员分配的账号。</p>
        <form @submit.prevent="login"><label>账号<input v-model.trim="loginForm.username" required autocomplete="username" maxlength="64" /></label><label>密码<input v-model="loginForm.password" required type="password" autocomplete="current-password" maxlength="128" /></label><button class="primary" :disabled="busy">{{ busy ? '正在验证…' : '登录控制台' }}</button></form>
        <p v-if="error" class="error" role="alert">{{ error }}</p><a href="/admin/">前往商家经营后台 →</a><small>首次部署请由运维运行首位平台管理员初始化命令，无公开注册入口。</small>
      </section>
    </div>
    <div v-else class="workspace">
      <aside><div class="brand"><ShieldCheck :size="23" /><span>会员管家<small>平台控制台</small></span></div><nav aria-label="平台管理导航"><button v-for="item in navigation" :key="item.key" :class="{ active: tab === item.key }" @click="navigate(item.key)"><component :is="item.icon" :size="18" />{{ item.label }}</button></nav><div class="operator"><strong>{{ user.displayName }}</strong><small>{{ roleNames[user.role] }}</small><button @click="logout" :disabled="busy">退出平台账号</button></div></aside>
      <div class="work-area"><header><div><span class="eyebrow">平台 / {{ currentTitle }}</span><h1>{{ currentTitle }}</h1></div><span class="scope">跨门店 · 平台权限</span></header>
        <main><p v-if="error" class="error" role="alert">{{ error }}</p><p v-if="message" class="success" role="status">{{ message }}</p>
          <template v-if="tab === 'stores'">
            <section class="panel"><div class="section-heading"><div><h2>门店目录</h2><p>按名称前缀查询，管理门店状态及商业授权。</p></div><button :disabled="busy" @click="loadStores(false)">刷新</button></div>
              <form class="toolbar" @submit.prevent="loadStores(false)"><label class="search">查询门店名称<input v-model.trim="search" maxlength="64" placeholder="输入名称前缀" /></label><button type="submit" :disabled="busy">查询</button><button v-if="can('stores.write')" type="button" @click="showCreate = !showCreate">{{ showCreate ? '收起创建表单' : '创建门店' }}</button></form>
              <form v-if="showCreate && can('stores.write')" class="form-grid inset" @submit.prevent="createStore"><label>门店名称<input v-model.trim="newStore.storeName" required maxlength="128" /></label><label>店主姓名<input v-model.trim="newStore.displayName" required maxlength="128" /></label><label>店主登录账号<input v-model.trim="newStore.username" required pattern="[a-zA-Z0-9_.@-]{3,64}" autocomplete="off" /></label><label>初始密码<input v-model="newStore.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" /></label><div class="form-footer"><small>创建后尚未授权，需要在下方配置在线授权或签发离线授权。</small><button class="primary" :disabled="busy">创建门店与店主</button></div></form>
              <div class="table-wrap"><table><thead><tr><th>门店</th><th>状态</th><th>在线授权</th><th>管理</th></tr></thead><tbody><tr v-for="store in stores" :key="store.id" :class="{ selected: selected?.id === store.id }"><td><strong>{{ store.name }}</strong><small class="identifier">{{ store.id }}</small></td><td><span class="badge" :class="{ muted: store.status !== 'active' }">{{ store.status === 'active' ? '营业中' : '平台停用' }}</span></td><td>{{ licenseLabel(store) }}<small v-if="store.expires_at">{{ date(store.expires_at) }}</small></td><td><div class="actions"><button @click="selectStore(store)" :disabled="busy">管理</button><button v-if="can('stores.write')" :disabled="busy" @click="toggleStore(store)">{{ store.status === 'active' ? '停用门店' : '恢复门店' }}</button></div></td></tr><tr v-if="!stores.length"><td colspan="4">{{ busy ? '正在加载…' : '暂无匹配门店' }}</td></tr></tbody></table></div><button v-if="storesPageFull" :disabled="busy" @click="loadStores(true)">加载更多门店</button>
            </section>
            <section v-if="selected" class="panel"><div class="section-heading"><div><span class="eyebrow">当前管理门店</span><h2>{{ selected.name }}</h2><small class="identifier">{{ selected.id }}</small></div><button @click="selected = null">收起</button></div>
              <div v-if="can('licenses.read')" class="license-columns"><form class="inset" @submit.prevent="saveLicense('policy')"><h3>在线商业授权</h3><p>服务端实时校验。设备离线期限同时受本策略和店主设备设置限制。</p><label class="checkbox"><input v-model="licenseForm.active" type="checkbox" :disabled="!can('licenses.write')" />允许在线使用</label><label>最长离线小时数（0 为必须在线）<input v-model.number="licenseForm.offlineHours" type="number" min="0" max="8760" required :disabled="!can('licenses.write')" /></label><fieldset :disabled="!can('licenses.write')"><legend>开放功能</legend><label v-for="feature in features" :key="feature" class="checkbox"><input v-model="licenseForm.features" type="checkbox" :value="feature" />{{ featureNames[feature] }}</label></fieldset><p>当前期限：{{ licenseData?.online ? licenseData.online.expires_at ? date(licenseData.online.expires_at) : '永久' : '尚未授权' }}</p><button v-if="can('licenses.write')" type="submit" :disabled="busy || !licenseData?.online">保存功能与状态（保留期限）</button><fieldset v-if="can('licenses.write')"><legend>签发或续期 · 自当前时间起</legend><label>期限类型<select v-model="licenseForm.permanent"><option :value="false">按天授权</option><option :value="true">永久授权</option></select></label><label v-if="!licenseForm.permanent">授权天数<input v-model.number="licenseForm.days" type="number" min="1" max="36500" required /></label><button type="button" class="primary" :disabled="busy" @click="saveLicense('renew')">按所选期限签发 / 续期</button></fieldset></form>
                <form v-if="can('licenses.write')" class="inset" @submit.prevent="issueOffline"><h3>签发独立离线授权</h3><p>无需连接服务器。授权绑定一台设备；签发后无法向断网设备即时撤销。</p><label>App 设备标识<input v-model.trim="offlineForm.deviceId" required minlength="16" maxlength="80" placeholder="从 App 授权页复制" /></label><label>本地登录账号<input v-model.trim="offlineForm.username" required pattern="[a-zA-Z0-9_.@-]{3,64}" /></label><label>本地账号姓名<input v-model.trim="offlineForm.displayName" required maxlength="128" /></label><label>期限类型<select v-model="offlineForm.permanent"><option :value="false">按天授权</option><option :value="true">永久授权</option></select></label><label v-if="!offlineForm.permanent">授权天数<input v-model.number="offlineForm.days" type="number" required min="1" max="36500" /></label><fieldset><legend>离线开放功能</legend><label v-for="feature in offlineFeatures" :key="feature" class="checkbox"><input v-model="offlineForm.features" type="checkbox" :value="feature" />{{ featureNames[feature] }}</label></fieldset><button class="primary" :disabled="busy">签发设备授权码</button><template v-if="issuedCode"><label>本次授权码<textarea :value="issuedCode" readonly rows="5" aria-label="已签发的离线授权码" /></label><button type="button" @click="copyCode">复制授权码</button><small>请安全交付并保存。服务端仅保存摘要，关闭后不能恢复原码。</small></template></form></div>
              <div v-if="licenseData?.offline.length" class="inset"><h3>最近离线签发记录</h3><div class="table-wrap"><table><thead><tr><th>设备</th><th>签发时间</th><th>到期时间</th></tr></thead><tbody><tr v-for="license in licenseData.offline" :key="license.id"><td class="identifier">{{ license.device_id }}</td><td>{{ date(license.issued_at) }}</td><td>{{ license.payload.expiresAt ? date(license.payload.expiresAt) : '永久' }}</td></tr></tbody></table></div></div>
              <div v-if="can('users.read')" class="inset"><h3>门店账号</h3><p>平台停用独立于商家停用，店主不能自行解除平台限制。</p><div class="table-wrap"><table><thead><tr><th>用户</th><th>门店角色</th><th>状态</th><th v-if="can('users.write')">平台操作</th></tr></thead><tbody><tr v-for="member in users" :key="member.id"><td>{{ member.display_name }}<small>{{ member.username }}</small></td><td><select v-model="member.role" :disabled="!can('users.write')" aria-label="门店用户角色"><option value="owner">店主</option><option value="clerk">店员</option><option value="viewer">只读</option></select></td><td>{{ member.platform_disabled ? '平台禁用' : member.active ? '在用' : '商家停用' }}</td><td v-if="can('users.write')"><div class="actions"><button :disabled="busy" @click="saveUser(member, member.platform_disabled)">保存角色</button><button :disabled="busy" @click="saveUser(member, !member.platform_disabled)">{{ member.platform_disabled ? '解除平台禁用' : '平台禁用' }}</button></div><form class="inline-form" @submit.prevent="saveUser(member, member.platform_disabled, true)"><input v-model="member.newPassword" type="password" minlength="12" maxlength="128" required placeholder="新密码（至少 12 位）" aria-label="重置用户密码" autocomplete="new-password" /><button :disabled="busy">重置密码</button></form></td></tr></tbody></table></div></div>
            </section>
          </template>
          <section v-else-if="tab === 'logs'" class="panel"><div class="section-heading"><div><h2>日志查询</h2><p>手动按页读取，单页 50 条。诊断只采样成功请求，错误请求进入有界队列。</p></div></div><form class="toolbar" @submit.prevent="loadLogs(false)"><label>日志来源<select v-model="logKind"><option value="platform">平台管理审计</option><option value="merchant">全部门店操作审计</option><option value="diagnostic">API 请求诊断</option></select></label><label v-if="logKind !== 'diagnostic'">门店 ID（可选）<input v-model.trim="logStore" placeholder="留空查询全部门店" /></label><button :disabled="busy">查询最新记录</button></form><div class="table-wrap"><table><thead><tr><th>时间</th><th>事件 / 路由</th><th>账号 / 请求</th><th>详情</th></tr></thead><tbody><tr v-for="event in logs" :key="event.id"><td>{{ date(event.received_at) }}</td><td>{{ event.event || event.route }}<small v-if="event.store_id">{{ event.store_id }}</small></td><td>{{ event.display_name || event.request_id || '系统' }}</td><td><code>{{ event.details ? JSON.stringify(event.details) : event.status + ' · ' + event.duration_ms + ' ms · ' + (event.error_code || '成功') }}</code></td></tr><tr v-if="!logs.length"><td colspan="4">暂无记录，请选择来源后查询。</td></tr></tbody></table></div><button v-if="logsPageFull" :disabled="busy" @click="loadLogs(true)">加载更早记录</button></section>
          <section v-else-if="tab === 'operators'" class="panel"><div class="section-heading"><div><h2>平台团队与权限</h2><p>超级管理员管理全部能力；运营负责门店与授权；开发者查看诊断；审计员只读查询。</p></div><button :disabled="busy" @click="loadOperators">刷新</button></div><div class="table-wrap"><table><thead><tr><th>账号</th><th>角色</th><th>状态</th><th>管理</th></tr></thead><tbody><tr v-for="operator in operators" :key="operator.id"><td>{{ operator.displayName }}<small>{{ operator.username }}</small></td><td>{{ roleNames[operator.role] }}</td><td>{{ operator.active ? '在用' : '停用' }}</td><td><button v-if="can('operators.write')" :disabled="busy" @click="editOperator(operator)">编辑</button></td></tr></tbody></table></div><form v-if="can('operators.write')" class="form-grid inset" @submit.prevent="saveOperator"><h3 class="full">{{ operatorForm.id ? '修改平台账号' : '新增平台账号' }}</h3><label>登录账号<input v-model.trim="operatorForm.username" :readonly="Boolean(operatorForm.id)" required pattern="[a-zA-Z0-9_.@-]{3,64}" /></label><label>姓名<input v-model.trim="operatorForm.displayName" required maxlength="128" /></label><label>角色<select v-model="operatorForm.role"><option v-for="(label, role) in roleNames" :key="role" :value="role">{{ label }}</option></select></label><label>{{ operatorForm.id ? '新密码（留空不变）' : '初始密码' }}<input v-model="operatorForm.password" type="password" :required="!operatorForm.id" minlength="12" maxlength="128" autocomplete="new-password" /></label><label class="checkbox"><input v-model="operatorForm.active" type="checkbox" />启用账号</label><div class="actions full"><button class="primary" :disabled="busy">保存平台账号</button><button type="button" @click="resetOperator">清空表单</button></div></form></section>
          <section v-else-if="tab === 'system'" class="panel"><div class="section-heading"><div><h2>运行状态与开发接入</h2><p>就绪探针 /api/ready；存活探针 /api/health。</p></div><button :disabled="busy" @click="loadSystem">刷新状态</button></div><dl class="status-grid"><div><dt>服务状态</dt><dd>{{ system?.status || '待查询' }}</dd></div><div><dt>离线签发密钥</dt><dd>{{ system?.signer?.keyId || '未配置' }}</dd></div><div><dt>诊断队列</dt><dd>{{ system?.diagnostics?.queued ?? '—' }}</dd></div><div><dt>诊断丢弃计数（本实例）</dt><dd>{{ system?.diagnostics?.dropped ?? '—' }}</dd></div></dl><h3>当前架构边界</h3><p>会员、账户、流水、成交明细、配置与审计在 PostgreSQL 中按店拆表保存；资金写入使用事务，恢复后切换账本代际。默认部署是单数据库、单 API；集群、主备和数据库拆分需按运维文档实施并演练。</p><p>平台接口前缀 /api/platform/v1；账务接口前缀 /api/v2；登录和管理接口使用 /api/v1。两套身份和令牌隔离。完整权限、恢复、密钥轮换和扩容说明位于仓库 docs/。</p><details v-if="system?.signer"><summary>App 构建所需公钥（可公开）</summary><pre>{{ JSON.stringify({ [system.signer.keyId]: system.signer.publicKey }, null, 2) }}</pre></details></section>
          <section v-else-if="tab === 'account'" class="panel narrow"><h2>账号安全</h2><p>修改密码会撤销此平台账号的所有会话。</p><form @submit.prevent="changePassword"><label>当前密码<input v-model="passwordForm.currentPassword" type="password" required autocomplete="current-password" /></label><label>新密码<input v-model="passwordForm.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" /></label><button class="primary" :disabled="busy">修改并重新登录</button></form></section>
        </main><footer>平台控制面 · 身份隔离 / 设备授权 / 可追溯审计</footer>
      </div>
    </div>
  </div>
</template>
<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';
import { ShieldCheck, Store, ScrollText, UsersRound, Server, KeyRound } from 'lucide-vue-next';
import { PlatformClient } from './api/platform-client.js';
import { LICENSE_FEATURES } from '../../src/license-policy.js';
const api = new PlatformClient();
const user = ref(null), tab = ref('stores'), busy = ref(false), error = ref(''), message = ref('');
const loginForm = ref({ username: '', password: '' }), roleNames = { superadmin: '平台超级管理员', operator: '运营管理员', developer: '开发者', auditor: '平台审计员' };
const features = LICENSE_FEATURES, offlineFeatures = features.filter(feature => !['voice', 'staff', 'devices'].includes(feature));
const featureNames = { core: '基础访问', members: '会员管理', cashier: '收银记账', reports: '经营报表', backup: '备份与恢复', voice: '云端语音', staff: '员工管理', devices: '设备管理', settings: '经营设置' };
const stores = ref([]), search = ref(''), storesPageFull = ref(false), selected = ref(null), showCreate = ref(false), users = ref([]), licenseData = ref(null), issuedCode = ref('');
const newStore = ref({ storeName: '', displayName: '', username: '', password: '' });
const licenseForm = ref({ active: true, offlineHours: 0, permanent: false, days: 365, features: [...features] });
const offlineForm = ref({ deviceId: '', username: '', displayName: '', permanent: false, days: 365, features: [...offlineFeatures] });
const logs = ref([]), logsPageFull = ref(false), logKind = ref('platform'), logStore = ref(''), operators = ref([]), system = ref(null), operatorForm = ref({}), passwordForm = ref({ currentPassword: '', password: '' });
let lastActivity = Date.now(), idleTimer;
function resetWorkspace() {
  selected.value = null; issuedCode.value = ''; stores.value = []; users.value = []; licenseData.value = null;
  logs.value = []; operators.value = []; system.value = null; search.value = ''; showCreate.value = false;
  newStore.value = { storeName: '', displayName: '', username: '', password: '' };
  offlineForm.value = { deviceId: '', username: '', displayName: '', permanent: false, days: 365, features: [...offlineFeatures] };
  passwordForm.value = { currentPassword: '', password: '' }; resetOperator();
}
function touch() { lastActivity = Date.now(); }
function can(permission) { return user.value?.permissions?.includes(permission); }
const navigation = computed(() => [
  { key: 'stores', label: '门店与商业授权', icon: Store, permission: 'stores.read' },
  { key: 'logs', label: '审计与请求日志', icon: ScrollText, permission: 'logs.read' },
  { key: 'operators', label: '平台团队', icon: UsersRound, permission: 'operators.read' },
  { key: 'system', label: '运行状态与接入', icon: Server, permission: 'system.read' },
  { key: 'account', label: '账号安全', icon: KeyRound }
].filter(item => !item.permission || can(item.permission)));
const currentTitle = computed(() => navigation.value.find(item => item.key === tab.value)?.label || '平台控制台');
function date(value) { return new Date(value).toLocaleString('zh-CN'); }
function licenseLabel(store) { return store.license_active === null ? '尚未授权' : !store.license_active ? '授权停用' : store.expires_at && Date.parse(store.expires_at) <= Date.now() ? '已到期' : '已授权'; }
async function act(action, success = '') {
  if (busy.value) return; busy.value = true; error.value = ''; message.value = '';
  try { await action(); if (success) message.value = success; }
  catch (failure) { if (failure.status === 401) { user.value = null; resetWorkspace(); } error.value = failure.message + (failure.requestId ? '（请求 ' + failure.requestId + '）' : ''); }
  finally { if (!user.value) resetWorkspace(); busy.value = false; }
}
async function login() { await act(async () => { const nextUser = await api.login(loginForm.value.username, loginForm.value.password); resetWorkspace(); user.value = nextUser; loginForm.value.password = ''; touch(); tab.value = navigation.value[0]?.key || 'account'; await loadCurrent(); }); }
async function logout() { await act(async () => { try { await api.logout(); } finally { user.value = null; resetWorkspace(); } }); }
async function navigate(key) { if (busy.value) return; tab.value = key; error.value = ''; message.value = ''; await act(loadCurrent); }
async function loadCurrent() { if (tab.value === 'stores') await fetchStores(false); if (tab.value === 'logs') await fetchLogs(false); if (tab.value === 'operators') operators.value = await api.request('/operators'); if (tab.value === 'system') system.value = await api.request('/system'); }
async function fetchStores(append) { const query = new URLSearchParams({ limit: '50', search: search.value }); if (append && stores.value.length) query.set('before', stores.value.at(-1).id); const rows = await api.request('/stores?' + query); stores.value = append ? [...stores.value, ...rows] : rows; storesPageFull.value = rows.length === 50; }
function loadStores(append) { return act(() => fetchStores(append)); }
async function createStore() { await act(async () => { await api.request('/stores', newStore.value); showCreate.value = false; newStore.value = { storeName: '', displayName: '', username: '', password: '' }; await fetchStores(false); }, '门店已创建，请配置商业授权。'); }
async function toggleStore(store) { if (!confirm((store.status === 'active' ? '停用后，该门店的在线业务请求将被拒绝。确认停用 ' : '确认恢复 ') + store.name + '？')) return; await act(async () => { await api.request('/stores/' + store.id, { status: store.status === 'active' ? 'suspended' : 'active', expectedVersion: store.version }, 'PATCH'); await fetchStores(false); if (selected.value?.id === store.id) selected.value = stores.value.find(item => item.id === store.id) || null; }, '门店状态已更新。独立离线授权不受远程状态即时控制。'); }
async function fetchDetails(store) {
  selected.value = store; users.value = []; licenseData.value = null; issuedCode.value = '';
  if (can('licenses.read')) { licenseData.value = await api.request('/stores/' + store.id + '/license'); const current = licenseData.value.online; licenseForm.value = { active: current?.active ?? true, offlineHours: current?.offline_hours ?? 0, permanent: current ? !current.expires_at : false, days: current?.expires_at ? Math.max(1, Math.ceil((Date.parse(current.expires_at) - Date.now()) / 86400000)) : 365, features: [...(current?.features || features)] }; }
  if (can('users.read')) users.value = await api.request('/stores/' + store.id + '/users');
}
function selectStore(store) { return act(() => fetchDetails(store)); }
async function saveLicense(action) { await act(async () => { const input = { ...licenseForm.value, action, days: licenseForm.value.permanent ? null : licenseForm.value.days, expectedVersion: licenseData.value?.online?.version ?? -1 }; await api.request('/stores/' + selected.value.id + '/license', input); const store = selected.value; await fetchStores(false); await fetchDetails(stores.value.find(row => row.id === store.id) || store); }, '在线授权策略已更新。联网设备将在下一次校验时生效。'); }
async function issueOffline() { await act(async () => { const result = await api.request('/stores/' + selected.value.id + '/offline-licenses', { ...offlineForm.value, days: offlineForm.value.permanent ? null : offlineForm.value.days }); issuedCode.value = result.code; licenseData.value = await api.request('/stores/' + selected.value.id + '/license'); }, '离线授权码已签发，请安全交付到指定设备。'); }
async function copyCode() { try { await navigator.clipboard.writeText(issuedCode.value); message.value = '授权码已复制'; } catch { error.value = '复制失败，请选中授权码手动复制。'; } }
async function saveUser(member, disabled, reset = false) { if (disabled && !member.platform_disabled && !confirm('确认平台禁用此账号？已连接的会话将失效。')) return; await act(async () => { await api.request('/users/' + member.id, { storeId: selected.value.id, disabled, role: member.role, expectedVersion: member.version, ...(reset ? { password: member.newPassword } : {}) }, 'PATCH'); users.value = await api.request('/stores/' + selected.value.id + '/users'); }, '用户权限已更新；该用户需要重新登录。'); }
async function fetchLogs(append) { const query = new URLSearchParams({ kind: logKind.value, limit: '50' }); if (logKind.value !== 'diagnostic' && logStore.value) query.set('storeId', logStore.value); if (append && logs.value.length) query.set('before', logs.value.at(-1).id); const rows = await api.request('/logs?' + query); logs.value = append ? [...logs.value, ...rows] : rows; logsPageFull.value = rows.length === 50; }
function loadLogs(append) { return act(() => fetchLogs(append)); }
function resetOperator() { operatorForm.value = { id: '', username: '', displayName: '', role: 'developer', active: true, password: '' }; }
function editOperator(operator) { operatorForm.value = { ...operator, expectedVersion: operator.version, password: '' }; }
function loadOperators() { return act(async () => { operators.value = await api.request('/operators'); }); }
async function saveOperator() { await act(async () => { const input = { ...operatorForm.value }; if (input.id && !input.password) delete input.password; await api.request('/operators' + (input.id ? '/' + input.id : ''), input, input.id ? 'PATCH' : 'POST'); if (input.id === user.value.id) { api.clear(); user.value = null; } else operators.value = await api.request('/operators'); resetOperator(); }, '平台账号已保存。角色或密码变更会撤销旧会话。'); }
function loadSystem() { return act(async () => { system.value = await api.request('/system'); }); }
async function changePassword() { await act(async () => { await api.request('/auth/password', passwordForm.value); api.clear(); user.value = null; passwordForm.value = { currentPassword: '', password: '' }; }, '密码已更新，请重新登录。'); }
resetOperator();
onMounted(async () => { if (api.token) await act(async () => { user.value = await api.request('/auth/me'); tab.value = navigation.value[0]?.key || 'account'; await loadCurrent(); }); idleTimer = setInterval(() => { if (user.value && Date.now() - lastActivity >= 15 * 60000 && !busy.value) void logout(); }, 15000); });
onUnmounted(() => clearInterval(idleTimer));
</script>
